struct event_data {
    struct coresight_device *sink;
    struct work_struct free_work;
    struct list_head paths;
};

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite)
{
    struct event_data *data;
    struct coresight_device *sink;
    struct coresight_path *path;

    data = kzalloc(sizeof(*data), GFP_KERNEL);
    if (!data)
        return NULL;

    INIT_WORK(&data->free_work, NULL);
    INIT_LIST_HEAD(&data->paths);

    sink = coresight_get_enabled_sink(event_cpu);
    if (!sink) {
        kfree(data);
        return NULL;
    }

    if (!sink->alloc_buffer) {
        kfree(data);
        return NULL;
    }

    data->sink = sink;

    path = sink->alloc_buffer(sink, event_cpu, pages, nr_pages, overwrite);
    if (!path) {
        kfree(data);
        return NULL;
    }

    list_add_tail(&path->node, &data->paths);

    return data;
}

#include <linux/slab.h>
#include <linux/workqueue.h>
#include <linux/percpu.h>
#include <linux/coresight.h>

void *setup_aux_event_data(int event_cpu, void **pages, int nr_pages, bool overwrite)
{
    struct aux_event_data *event_data;
    struct coresight_device *sink;

    event_data = kzalloc(sizeof(*event_data), GFP_KERNEL);
    if (!event_data)
        return NULL;

    sink = coresight_get_enabled_sink();
    if (!sink) {
        kfree(event_data);
        return NULL;
    }

    if (!sink->ops->alloc_buffer || !sink->ops->free_buffer) {
        kfree(event_data);
        return NULL;
    }

    event_data->sink = sink;
    event_data->cpu = event_cpu;
    event_data->overwrite = overwrite;

    INIT_WORK(&event_data->free_work, free_event_data_work);

    for_each_cpu(event_cpu) {
        struct aux_path *path = kzalloc(sizeof(*path), GFP_KERNEL);
        if (!path) {
            cleanup_event_data(event_data);
            return NULL;
        }

        path->cpu = event_cpu;
        path->pages = pages;
        path->nr_pages = nr_pages;

        if (sink->ops->setup_path(sink, path)) {
            kfree(path);
            cleanup_event_data(event_data);
            return NULL;
        }

        event_data->paths[event_cpu] = path;
    }

    if (sink->ops->alloc_buffer(sink, event_data)) {
        cleanup_event_data(event_data);
        return NULL;
    }

    return event_data;
}

